              "curl": "curl -X POST \"https://api.nextmoe.dev/v2/me/proposals\" \\\n  -H \"Authorization: Bearer <ACCESS_TOKEN>\" \\\n  -H \"Content-Type: application/json\" \\\n  -d '{\"entity_id\":\"string\",\"entity_type\":\"string\",\"patch\":{\"key\":\"string\"}}'"
